ROLES = {
    "domain-viewer": {"scope": "DOMAIN",  "perms": ["inventory.*.list", "inventory.*.get"]},
    "project-admin": {"scope": "PROJECT", "perms": ["inventory.Server.*"]},
}

def match(pattern, perm):
    return all(p in ("*", q) for p, q in zip(pattern.split("."), perm.split(".")))

def allowed(user, perm, domain_id, project_id):
    if user["domain_id"] != domain_id:          # 다른 고객사 데이터는 권한 이전에 막는다
        return False
    role = ROLES[user["role"]]
    if role["scope"] == "PROJECT" and project_id not in user["projects"]:
        return False
    return any(match(p, perm) for p in role["perms"])

kim = {"domain_id": "d-acme", "role": "project-admin", "projects": ["p-web"]}
lee = {"domain_id": "d-acme", "role": "domain-viewer", "projects": []}
print(allowed(kim, "inventory.Server.delete", "d-acme", "p-web"))   # True
print(allowed(kim, "inventory.Server.delete", "d-acme", "p-batch")) # False 다른 프로젝트
print(allowed(lee, "inventory.Server.delete", "d-acme", "p-web"))   # False 보기 전용
print(allowed(lee, "inventory.Server.list",  "d-other", "p-x"))     # False 다른 테넌트
